# builder/gen_ch19_p3.py
# -*- coding: utf-8 -*-

exercises = [{'num': 57, 'title': 'Логирование паники через log.Panicf и восстановление через recover', 'task': 'Используй `log.Panicf("Unexpected: %v", err)`. Покажи разницу с `Fatalf`: `panic` можно `recover`, `log.Fatalf` — нет (мгновенный выход).', 'theory': '`log.Panicf` форматирует строку, записывает её в поток логов и вызывает встроенную панику `panic(msg)`. Это позволяет раскрутить стек вызовов и перехватить ошибку через `recover()` в `defer` функции.', 'step_by_step': '1. Запустим защищенную функцию с `defer func() { if r := recover(); r != nil { ... } }()`.\n2. Вызовем `log.Panicf`.\n3. Перехватим панику и продолжим выполнение программы.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n\t"log"\n)\n\nfunc safeWorker() {\n\tdefer func() {\n\t\tif r := recover(); r != nil {\n\t\t\tfmt.Printf("[RECOVERED] Паника успешно перехвачена: %v\\n", r)\n\t\t}\n\t}()\n\n\terr := errors.New("некорректный формат токена JWT")\n\tlog.Panicf("Фатальная ошибка парсинга: %v", err)\n\n\tfmt.Println("Этот код не выполнится")\n}\n\nfunc main() {\n\tlog.Println("Старт программы")\n\tsafeWorker()\n\tlog.Println("Программа успешно продолжила работу после recover!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 2026/09/02 18:40:00 Старт программы\n# 2026/09/02 18:40:00 Фатальная ошибка парсинга: некорректный формат токена JWT\n# [RECOVERED] Паника успешно перехвачена: Фатальная ошибка парсинга: некорректный формат токена JWT\n# 2026/09/02 18:40:00 Программа успешно продолжила работу после recover!'}], 'under_the_hood': '`log.Panicf` генерирует панику со строкой, сформированной `fmt.Sprintf`.', 'pitfalls': '`log.Fatalf` невозможно перехватить через `recover()`, так как `os.Exit` не вызывает панику, а напрямую прерывает процесс.', 'bigtech_interview': '**Вопрос с собеседования:** «Когда следует использовать log.Panicf вместо log.Fatalf?»\n**Ответ:** `log.Panicf` используется внутри транзакционных обработчиков или фоновых воркеров, где сбой одной горутины должен быть залогирован и изолирован через `recover()`, не роняя весь HTTP-сервер.'}, {'num': 58, 'title': 'Сравнительный анализ механики log.Fatal и log.Panic', 'task': '**Фатальные ошибки и Паника**: Напишите код, демонстрирующий разницу между вызовами `log.Fatal` (вызывает `os.Exit(1)`) и `log.Panic` (вызывает панику, которую можно перехватить через `recover`). Убедитесь, что после `log.Fatal` код, написанный ниже, и операторы `defer` не выполняются.', 'theory': 'Разница между `log.Fatal` и `log.Panic`:\n1. `log.Fatal` -> `l.Output()` + `os.Exit(1)` (нет unwinding, `defer` игнорируются).\n2. `log.Panic` -> `l.Output()` + `panic(s)` (unwinding стека, `defer` выполняются, возможен `recover`).', 'step_by_step': '1. Напишем демонстрационную функцию с `log.Panic` и проверим выполнение `defer`.\n2. Опишем поведение `log.Fatal`.\n3. В `main` сравним оба механизма.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log"\n)\n\nfunc demoPanic() {\n\tdefer fmt.Println(" -> [DEFER in demoPanic] Этот defer выполнился успешно!")\n\tdefer func() {\n\t\tif r := recover(); r != nil {\n\t\t\tfmt.Printf(" -> [RECOVER] Перехвачено: %v\\n", r)\n\t\t}\n\t}()\n\n\tlog.Panicln("Вызов log.Panicln: инициирована паника")\n}\n\nfunc main() {\n\tfmt.Println("=== 1. Тестирование log.Panic ===")\n\tdemoPanic()\n\n\tfmt.Println("\\n=== 2. Специфика log.Fatal ===")\n\tfmt.Println("log.Fatal(msg) немедленно прерывает процесс: os.Exit(1)")\n\tfmt.Println("Ни один defer в вызывающем стеке не выполнится.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# === 1. Тестирование log.Panic ===\n# 2026/09/02 18:40:00 Вызов log.Panicln: инициирована паника\n#  -> [RECOVER] Перехвачено: Вызов log.Panicln: инициирована паника\n#  -> [DEFER in demoPanic] Этот defer выполнился успешно!\n# \n# === 2. Специфика log.Fatal ===\n# log.Fatal(msg) немедленно прерывает процесс: os.Exit(1)\n# Ни один defer в вызывающем стеке не выполнится.'}], 'under_the_hood': 'Рантайм Go обрабатывает `panic` путем последовательного вызова цепочки структур `_defer` в текущей `g` (горутине).', 'pitfalls': 'Если паника в горутине не перехвачена `recover()`, рантайм аварийно завершает весь процесс с дампом всех горутин.', 'bigtech_interview': '**Вопрос с собеседования:** «Что происходит с другими горутинами, если в одной из них произошла непойманная паника?»\n**Ответ:** Рантайм Go аварийно завершает весь процесс. Все параллельные горутины мгновенно уничтожаются без выполнения их `defer`.'}, {'num': 59, 'title': 'Файловый логгер с флагами os.O_APPEND | os.O_CREATE | os.O_WRONLY', 'task': 'Направь вывод кастомного логгера в файл (открой файл через `os.OpenFile` с флагами `os.O_APPEND|os.O_CREATE|os.O_WRONLY`).', 'theory': 'Комбинация флагов `os.O_APPEND|os.O_CREATE|os.O_WRONLY` с правами `0644` — канонический способ безопасного создания и дозаписи лог-файлов в Unix-системах.', 'step_by_step': '1. Откроем `custom_target.log`.\n2. Создадим экземпляр `log.New(file, "[AUDIT] ", log.LstdFlags)`.\n3. Запишем событие аудита.\n4. Проверим файл.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\tpath := "custom_target.log"\n\tfile, err := os.OpenFile(path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)\n\tif err != nil {\n\t\tlog.Fatalf("Не удалось открыть файл: %v", err)\n\t}\n\tdefer func() {\n\t\tfile.Close()\n\t\t_ = os.Remove(path)\n\t}()\n\n\tauditLogger := log.New(file, "[AUDIT] ", log.Ldate|log.Ltime)\n\tauditLogger.Println("Пользователь admin повысил привилегии для user_id=45")\n\n\tdata, _ := os.ReadFile(path)\n\tfmt.Println("--- Запись в custom_target.log ---")\n\tfmt.Print(string(data))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- Запись в custom_target.log ---\n# [AUDIT] 2026/09/02 18:40:00 Пользователь admin повысил привилегии для user_id=45'}], 'under_the_hood': 'Права `0644` означают `rw-r--r--` (владелец: чтение/запись, группа и остальные: только чтение).', 'pitfalls': 'Если у процесса нет прав на запись в директорию, `os.OpenFile` вернет `os.ErrPermission`.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем нужен флаг os.O_WRONLY, если мы пишем в файл?»\n**Ответ:** Чтобы ядро ОС открыло дескриптор в режиме Write-Only, экономя системные ресурсы и защищая от случайных попыток чтения из файла логов.'}, {'num': 60, 'title': 'Введение в log/slog: базовые вызовы slog.Info и slog.Error', 'task': '**Структурное логирование (`log/slog`, Go 1.21+)**: Импортируй `log/slog`. Вызови `slog.Info("сервер запущен")` и `slog.Error("ошибка базы")`.', 'theory': 'Пакет `log/slog` (стандарт Go 1.21+) объединяет простоту стандартной библиотеки со скоростью и структурированностью `uber-go/zap`.', 'step_by_step': '1. Импортируем `"log/slog"`.\n2. Вызовем `slog.Info("сервер запущен", "port", 8080)`.\n3. Вызовем `slog.Error("ошибка базы", "error", "connection timeout")`.\n4. В `main` убедимся в выводе.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log/slog"\n)\n\nfunc main() {\n\t// Базовые вызовы структурированного логирования\n\tslog.Info("сервер запущен", "port", 8080, "env", "stage")\n\tslog.Error("ошибка базы", "error", "connection timeout", "retry", 3)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 2026/09/02 18:40:00 INFO сервер запущен port=8080 env=stage\n# 2026/09/02 18:40:00 ERROR ошибка базы error="connection timeout" retry=3'}], 'under_the_hood': 'Дефолтный хендлер `slog.Default()` форматирует строки в читаемом консольном стиле с разделением уровней `INFO`/`ERROR`.', 'pitfalls': 'Не передавайте ошибки через `fmt.Sprintf` — передавайте их как пару `"error", err`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go 1.21 добавили log/slog, если уже были zap и zerolog?»\n**Ответ:** Чтобы дать экосистеме Go единый стандартный интерфейс (`slog.Handler`). Теперь авторы сторонних библиотек могут логировать через `slog`, а разработчик приложения подключает любой бэкенд (Zap, Zerolog, CloudWatch) в одном месте.'}, {'num': 61, 'title': 'JSON-форматирование логов в slog.NewJSONHandler для ELK', 'task': 'Используй `slog.NewJSONHandler(os.Stdout, nil)`. Выведи логи в JSON-формате. Покажи, как это упрощает парсинг логов системами сбора.', 'theory': 'JSON-логирование исключает необходимость написания сложных регулярных выражений (Grok Patterns) в Logstash/Fluentbit. Каждое поле доступно сразу в структурированном виде.', 'step_by_step': '1. Создадим `logger := slog.New(slog.NewJSONHandler(os.Stdout, nil))`.\n2. Запишем событие создания заказа с вложенными атрибутами.\n3. В `main` проверим валидный JSON.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log/slog"\n\t"os"\n)\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\n\tlogger.Info("Заказ успешно оформлен",\n\t\tslog.Int64("order_id", 849201),\n\t\tslog.String("customer_email", "buyer@corp.ru"),\n\t\tslog.Float64("total_amount", 12490.50),\n\t\tslog.String("payment_gateway", "SberPay"),\n\t)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Заказ успешно оформлен","order_id":849201,"customer_email":"buyer@corp.ru","total_amount":12490.5,"payment_gateway":"SberPay"}'}], 'under_the_hood': 'JSON-хендлер автоматически кодирует спецсимволы и кавычки внутри строк.', 'pitfalls': 'Не передавайте циклические структуры данных — сериализатор `slog` может вызвать ошибку переполнения стека.', 'bigtech_interview': '**Вопрос с собеседования:** «Как в ELK настроить автоматический парсинг JSON-логов из stdout контейнеров?»\n**Ответ:** Включить фильтр `json { source => "message" }` в Logstash или использовать процессор `json` в Fluent Bit / Vector.'}, {'num': 62, 'title': 'Изолированные логгеры infoLogger (Stdout) и errorLogger (Stderr)', 'task': '**Создание кастомного логгера**: Используя `log.New`, создайте два независимых логгера: `infoLogger` (с префиксом `[INFO] ` и выводом в `os.Stdout`) и `errorLogger` (с префиксом `[ERROR] ` и выводом в `os.Stderr`).', 'theory': 'Разделение логгеров по потокам `os.Stdout` (информация) и `os.Stderr` (ошибки) — классический Unix-паттерн, поддерживаемый всеми системами мониторинга.', 'step_by_step': '1. Создадим `infoLogger := log.New(os.Stdout, "[INFO] ", log.Ldate|log.Ltime)`.\n2. Создадим `errorLogger := log.New(os.Stderr, "[ERROR] ", log.Ldate|log.Ltime|log.Lshortfile)`.\n3. Запишем сообщения через оба логгера.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\tinfoLogger := log.New(os.Stdout, "[INFO] ", log.Ldate|log.Ltime)\n\terrorLogger := log.New(os.Stderr, "[ERROR] ", log.Ldate|log.Ltime|log.Lshortfile)\n\n\tinfoLogger.Println("HTTP сервер запущен и ожидает соединений")\n\terrorLogger.Println("Таймаут соединения с платежным шлюзом")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [INFO] 2026/09/02 18:40:00 HTTP сервер запущен и ожидает соединений\n# [ERROR] 2026/09/02 18:40:00 main.go:12: Таймаут соединения с платежным шлюзом'}], 'under_the_hood': 'Каждый инстанс `*log.Logger` имеет собственный внутренний мьютекс и буфер строки.', 'pitfalls': 'В PowerShell/cmd перенаправление потоков может вести себя иначе, чем в Linux bash.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем разделять info в stdout, а error в stderr на уровне контейнера?»\n**Ответ:** Чтобы оркестратор Kubernetes и Prometheus Alertmanager могли настроить автоматический алерт по метрике `container_stderr_bytes_total > 0` без парсинга тела каждого лога.'}, {'num': 63, 'title': 'Маскирование чувствительных данных в slog.Handler', 'task': 'Реализуйте кастомный `slog.Handler`, который скрывает (маскирует) чувствительные данные (например, слово "password") перед записью лога.', 'theory': 'Фильтрация чувствительных ключей через `ReplaceAttr` в `slog.HandlerOptions` выполняется на этапе форматирования записи.', 'step_by_step': '1. Создадим функцию маскирования.\n2. Проверим `a.Key == "password"`.\n3. Заменим значение на `slog.StringValue("******")`.\n4. В `main` вызовем логгер.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log/slog"\n\t"os"\n\t"strings"\n)\n\nfunc maskSensitive(groups []string, a slog.Attr) slog.Attr {\n\tif strings.EqualFold(a.Key, "password") || strings.EqualFold(a.Key, "secret") {\n\t\treturn slog.String(a.Key, "******")\n\t}\n\treturn a\n}\n\nfunc main() {\n\topts := &slog.HandlerOptions{\n\t\tReplaceAttr: maskSensitive,\n\t}\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, opts))\n\n\tlogger.Info("Попытка аутентификации пользователя",\n\t\tslog.String("username", "admin"),\n\t\tslog.String("password", "SuperSecretPass123"),\n\t\tslog.String("secret", "api-key-99182"),\n\t)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Попытка аутентификации пользователя","username":"admin","password":"******","secret":"******"}'}], 'under_the_hood': '`strings.EqualFold` выполняет сравнение строк без учета регистра символов ASCII.', 'pitfalls': 'Учитывайте русскоязычные ключи (`"пароль"`, `"секрет"`), если они могут появиться в коде.', 'bigtech_interview': '**Вопрос с собеседования:** «Как маскировать чувствительные данные в неструктурированном тексте msg?»\n**Ответ:** Скомпилировать регулярное выражение `regexp.MustCompile(`(?i)(password|token)=([^\\s&]+)`)` и заменять совпадения в функции `ReplaceAttr` для ключа `slog.MessageKey`.'}, {'num': 64, 'title': 'Дочерние логгеры подсистем через logger.With("module", "database")', 'task': 'Создайте дочерний логгер в `slog` с помощью `logger.With("module", "database")`, чтобы все последующие логи из этого модуля автоматически содержали это поле.', 'theory': 'Метод `logger.With(attrs...)` создает иммутабельный дочерний логгер с предзаполненными полями модуля.', 'step_by_step': '1. Создадим базовый логгер `rootLogger`.\n2. Создадим `dbLogger := rootLogger.With(slog.String("module", "database"))`.\n3. Создадим `apiLogger := rootLogger.With(slog.String("module", "http_api"))`.\n4. В `main` сравним логи из обоих модулей.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log/slog"\n\t"os"\n)\n\nfunc main() {\n\trootLogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\n\t// Создание дочерних логгеров с зафиксированным контекстом модуля\n\tdbLogger := rootLogger.With(slog.String("module", "database"))\n\tapiLogger := rootLogger.With(slog.String("module", "http_api"))\n\n\tdbLogger.Info("Выполнен SQL-запрос", "query", "SELECT * FROM users", "rows", 42)\n\tapiLogger.Info("Входящий HTTP-запрос", "method", "POST", "path", "/login")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Выполнен SQL-запрос","module":"database","query":"SELECT * FROM users","rows":42}\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Входящий HTTP-запрос","module":"http_api","method":"POST","path":"/login"}'}], 'under_the_hood': '`logger.With` предварительно кодирует атрибуты модуля в буфер хендлера один раз при создании.', 'pitfalls': 'Не пересоздавайте `logger.With` в цикле на каждой итерации — создайте его один раз при инициализации сервиса.', 'bigtech_interview': '**Вопрос с собеседования:** «Как With(attrs) влияет на производительность по сравнению с передачей атрибутов в каждый вызов Info?»\n**Ответ:** `logger.With` предварительно форматирует и кэширует общие атрибуты, сокращая накладные расходы сериализации в горячих путях.'}, {'num': 65, 'title': 'Обертка логгера с динамической фильтрацией уровней в Production', 'task': 'Напиши обёртку вокруг `log.Logger` или `slog.Logger` с методами `Debug`, `Info`, `Warn`, `Error`. Добавь уровень логирования и фильтрацию (не выводить Debug в production).', 'theory': 'Обертка логгера инкапсулирует логику фильтрации по уровням, защищая production-окружение от спама отладочных логов.', 'step_by_step': '1. Объявим структуру `AppLogger struct { minLevel slog.Level; logger *slog.Logger }`.\n2. Реализуем методы `Debug`, `Info`, `Warn`, `Error`.\n3. В методе `Debug` проверим `if l.minLevel <= slog.LevelDebug`.\n4. В `main` продемонстрируем работу в PROD режиме.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log/slog"\n\t"os"\n)\n\ntype AppLogger struct {\n\tminLevel slog.Level\n\thandler  slog.Handler\n}\n\nfunc NewAppLogger(minLevel slog.Level) *AppLogger {\n\treturn &AppLogger{\n\t\tminLevel: minLevel,\n\t\thandler:  slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{Level: minLevel}),\n\t}\n}\n\nfunc (l *AppLogger) Debug(msg string, args ...any) {\n\tslog.New(l.handler).Debug(msg, args...)\n}\n\nfunc (l *AppLogger) Info(msg string, args ...any) {\n\tslog.New(l.handler).Info(msg, args...)\n}\n\nfunc (l *AppLogger) Warn(msg string, args ...any) {\n\tslog.New(l.handler).Warn(msg, args...)\n}\n\nfunc (l *AppLogger) Error(msg string, args ...any) {\n\tslog.New(l.handler).Error(msg, args...)\n}\n\nfunc main() {\n\t// В проде устанавливаем уровень LevelInfo\n\tprodLog := NewAppLogger(slog.LevelInfo)\n\n\tfmt.Println("=== Режим Production (LevelInfo) ===")\n\tprodLog.Debug("Скрытый Debug-лог", "details", "verbose cache dump")\n\tprodLog.Info("Сервис запущен", "version", "1.0.0")\n\tprodLog.Error("Критический сбой диска", "path", "/dev/sda1")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# === Режим Production (LevelInfo) ===\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Сервис запущен","version":"1.0.0"}\n# {"time":"2026-09-02T18:40:00Z","level":"ERROR","msg":"Критический сбой диска","path":"/dev/sda1"}'}], 'under_the_hood': '`slog.Handler.Enabled` проверяет уровень до начала форматирования строк.', 'pitfalls': 'Не создавайте новый `slog.New` внутри каждого метода — сохраните `*slog.Logger` в структуре `AppLogger`.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем скрывать Debug логи в production?»\n**Ответ:** 1) Экономия дискового пространства и сети (Debug может составлять до 95% объема). 2) Предотвращение случайной утечки чувствительных внутренних данных. 3) Снижение нагрузки на CPU.'}, {'num': 66, 'title': 'Модульная система логирования с префиксами [DB] и [API]', 'task': 'Создайте кастомный логгер для каждого модуля приложения с префиксами `[DB]`, `[API]`.', 'theory': 'Модульные логгеры с текстовыми префиксами помогают быстро фильтровать логи в терминале при отладке без необходимости подключения тяжелых UI-систем.', 'step_by_step': '1. Создадим `dbLog := log.New(os.Stdout, "[DB] ", log.Ldate|log.Ltime)`.\n2. Создадим `apiLog := log.New(os.Stdout, "[API] ", log.Ldate|log.Ltime)`.\n3. Запишем сообщения из соответствующих слоев приложения.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log"\n\t"os"\n)\n\nfunc main() {\n\tflags := log.Ldate | log.Ltime\n\n\tdbLogger := log.New(os.Stdout, "[DB]  ", flags)\n\tapiLogger := log.New(os.Stdout, "[API] ", flags)\n\n\tdbLogger.Println("Пул соединений PostgreSQL инициализирован (max_conns=50)")\n\tapiLogger.Println("Маршрут POST /auth/login зарегистрирован")\n\tdbLogger.Println("Миграция 002_add_indexes применена успешно")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [DB]  2026/09/02 18:40:00 Пул соединений PostgreSQL инициализирован (max_conns=50)\n# [API] 2026/09/02 18:40:00 Маршрут POST /auth/login зарегистрирован\n# [DB]  2026/09/02 18:40:00 Миграция 002_add_indexes применена успешно'}], 'under_the_hood': 'Выравнивание префиксов пробелами `[DB]  ` и `[API] ` сохраняет вертикальную колонку таймстемпов ровной.', 'pitfalls': 'В больших распределенных системах префиксы заменяют на структурированные JSON поля `module`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как легко парсить префиксы модулей в логах?»\n**Ответ:** Использовать структурированный логгер `slog.With("module", "DB")`, который записывает модуль в отдельное JSON-поле, доступное для быстрой фильтрации.'}, {'num': 67, 'title': 'Универсальный Middleware полного аудита входящих HTTP-запросов', 'task': 'Напиши middleware для HTTP-обработчика (или просто функцию-обёртку), которая логирует: время начала, метод, путь, время выполнения, статус ответа, ошибку (если есть).', 'theory': 'Аудит HTTP-запросов объединяет метаданные маршрутизации, длительность обработки и возможные ошибки выполнения в единую структурированную запись.', 'step_by_step': '1. Создадим структуру `loggingRW` для перехвата статуса.\n2. В middleware зафиксируем `start := time.Now()`.\n3. В `defer` вызовем `logger.Info` или `logger.Error` в зависимости от статус-кода.\n4. В `main` протестируем выполнение запроса.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log/slog"\n\t"net/http"\n\t"net/http/httptest"\n\t"os"\n\t"time"\n)\n\ntype loggingRW struct {\n\thttp.ResponseWriter\n\tstatusCode int\n}\n\nfunc (lrw *loggingRW) WriteHeader(code int) {\n\tlrw.statusCode = code\n\tlrw.ResponseWriter.WriteHeader(code)\n}\n\nfunc FullAuditMiddleware(logger *slog.Logger) func(http.Handler) http.Handler {\n\treturn func(next http.Handler) http.Handler {\n\t\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\t\tstart := time.Now()\n\t\t\tlrw := &loggingRW{ResponseWriter: w, statusCode: http.StatusOK}\n\n\t\t\tdefer func() {\n\t\t\t\tlatency := time.Since(start)\n\t\t\t\tlvl := slog.LevelInfo\n\t\t\t\tif lrw.statusCode >= 500 {\n\t\t\t\t\tlvl = slog.LevelError\n\t\t\t\t} else if lrw.statusCode >= 400 {\n\t\t\t\t\tlvl = slog.LevelWarn\n\t\t\t\t}\n\n\t\t\t\tlogger.Log(r.Context(), lvl, "HTTP Request Completed",\n\t\t\t\t\tslog.String("method", r.Method),\n\t\t\t\t\tslog.String("path", r.URL.Path),\n\t\t\t\t\tslog.Int("status", lrw.statusCode),\n\t\t\t\t\tslog.Duration("latency", latency),\n\t\t\t\t\tslog.Time("started_at", start),\n\t\t\t\t)\n\t\t\t}()\n\n\t\t\tnext.ServeHTTP(lrw, r)\n\t\t})\n\t}\n}\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\tmw := FullAuditMiddleware(logger)\n\n\thandler := mw(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tw.WriteHeader(http.StatusOK)\n\t\t_, _ = w.Write([]byte("OK"))\n\t}))\n\n\treq := httptest.NewRequest(http.MethodGet, "/api/v1/health", nil)\n\trec := httptest.NewRecorder()\n\n\tfmt.Println("--- Выполнение HTTP-запроса через FullAuditMiddleware ---")\n\thandler.ServeHTTP(rec, req)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# --- Выполнение HTTP-запроса через FullAuditMiddleware ---\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"HTTP Request Completed","method":"GET","path":"/api/v1/health","status":200,"latency":12000,"started_at":"2026-09-02T18:40:00Z"}'}], 'under_the_hood': '`logger.Log(ctx, level, msg, attrs...)` позволяет динамически выбирать уровень записи (INFO для 200, WARN для 404, ERROR для 500).', 'pitfalls': 'Если заголовок ответа пишется через `w.WriteHeader`, повторный вызов `w.WriteHeader` вызовет предупреждение в консоли `http: superfluous response.WriteHeader call`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как предотвратить дублирование вызовов WriteHeader в кастомном ResponseWriter?»\n**Ответ:** Добавить булев флаг `wroteHeader bool` в структуру обертки. В методе `WriteHeader` проверять `if r.wroteHeader { return } r.wroteHeader = true; r.ResponseWriter.WriteHeader(code)`.'}, {'num': 68, 'title': 'Базовый синтаксис structured logging в slog с парами ключ-значение', 'task': '**Структурированный `slog` (База)**: Сделайте импорт современного пакета `log/slog` (доступен в современных версиях Go). Напишите вывод информационного лога `slog.Info`, передав туда сообщение и дополнительные параметры в виде пар "ключ-значение" (например, `slog.Info("user logged in", "user_id", 42, "ip", "127.0.0.1")`).', 'theory': 'Вариативные аргументы в `slog.Info(msg, ...any)` чередуются парами: нечетные параметры являются строковыми именами ключей, четные — значениями любых типов.', 'step_by_step': '1. Импортируем `"log/slog"`.\n2. Вызовем `slog.Info("user logged in", "user_id", 42, "ip", "127.0.0.1", "is_admin", true)`.\n3. В `main` убедимся в правильности форматирования.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log/slog"\n)\n\nfunc main() {\n\t// Базовый вывод пар ключ-значение\n\tslog.Info("user logged in",\n\t\t"user_id", 42,\n\t\t"ip", "127.0.0.1",\n\t\t"is_admin", true,\n\t)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 2026/09/02 18:40:00 INFO user logged in user_id=42 ip=127.0.0.1 is_admin=true'}], 'under_the_hood': '`slog` не использует строковую интерполяцию, передавая ключи и значения напрямую в парсер хендлера.', 'pitfalls': 'Ключи всегда должны быть строками (`string`). Передача числа в качестве ключа приведет к автоматическому форматированию имени ключа `!BADKEY`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему slog.Info("user login", "id", 42) лучше, чем log.Printf("user login: id=%d", 42)?»\n**Ответ:** Потому что поля `id` и `42` сохраняют свою семантическую структуру. При смене хендлера на JSON лог запишется как `{"id": 42}`, готовый к фильтрации в Kibana/Loki без регулярных выражений.'}, {'num': 69, 'title': 'Безопасная передача *slog.Logger и fallback на slog.Default()', 'task': 'Напишите функцию, которая принимает `*slog.Logger` в качестве аргумента. Это позволит вам легко передавать `nil` (что вызовет панику, проверьте `slog.Default()`) или мок-логгер при юнит-тестировании.', 'theory': 'Паттерн Fallback Logger защищает методы от паники при передаче `nil`: если переданный логгер равен `nil`, используется `slog.Default()`.', 'step_by_step': '1. Напишем функцию `ProcessOrder(logger *slog.Logger, orderID int)`.\n2. Добавим защиту: `if logger == nil { logger = slog.Default() }`.\n3. Протестируем вызов с реальным логгером и с `nil`.\n4. В `main` убедимся в стабильной работе.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log/slog"\n\t"os"\n)\n\nfunc ProcessOrder(logger *slog.Logger, orderID int) {\n\t// Fallback на глобальный дефолтный логгер при передаче nil\n\tif logger == nil {\n\t\tlogger = slog.Default()\n\t}\n\n\tlogger.Info("Обработка заказа в транзакционном сервисе", "order_id", orderID)\n}\n\nfunc main() {\n\tcustomLogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\n\tfmt.Println("=== 1. Вызов с кастомным JSON-логгером ===")\n\tProcessOrder(customLogger, 1001)\n\n\tfmt.Println("\\n=== 2. Вызов с nil (безопасный fallback на slog.Default) ===")\n\tProcessOrder(nil, 1002)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# === 1. Вызов с кастомным JSON-логгером ===\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Обработка заказа в транзакционном сервисе","order_id":1001}\n# \n# === 2. Вызов с nil (безопасный fallback на slog.Default) ===\n# 2026/09/02 18:40:00 INFO Обработка заказа в транзакционном сервисе order_id=1002'}], 'under_the_hood': '`slog.Default()` потокобезопасно возвращает атомарный указатель на текущий глобальный логгер.', 'pitfalls': 'Вызов методов на `nil` логгере без проверки (`logger.Info`) приведет к панике `runtime error: invalid memory address or nil pointer dereference`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как сделать логгер опциональным в структуре конфигурации (Options Pattern)?»\n**Ответ:** В конструкторе `NewService(opts Options)` выполнить проверку: `if opts.Logger == nil { opts.Logger = slog.Default() }`, гарантируя непустой логгер во всех методах.'}, {'num': 70, 'title': 'Установка глобального JSON логгера через slog.SetDefault', 'task': '**JSON Логирование**: Настройте `slog` так, чтобы он выводил логи исключительно в формате JSON. Для этого создайте новый логгер: `logger := slog.New(slog.NewJSONHandler(os.Stdout, nil))` и установите его как глобальный логгер по умолчанию с помощью `slog.SetDefault(logger)`. Выведите лог и посмотрите на структуру JSON.', 'theory': '`slog.SetDefault(logger)` переключает весь глобальный механизм логирования Go (включая `slog.Info`, `slog.Warn` и пакет `log`) на новый JSON-обработчик.', 'step_by_step': '1. Создадим `handler := slog.NewJSONHandler(os.Stdout, nil)`.\n2. Создадим `logger := slog.New(handler)`.\n3. Вызовем `slog.SetDefault(logger)`.\n4. Вызовем глобальный `slog.Info` и стандартный `log.Println`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log"\n\t"log/slog"\n\t"os"\n)\n\nfunc main() {\n\t// 1. Создаем JSON-логгер\n\tjsonHandler := slog.NewJSONHandler(os.Stdout, nil)\n\tlogger := slog.New(jsonHandler)\n\n\t// 2. Устанавливаем как дефолтный для всего приложения\n\tslog.SetDefault(logger)\n\n\t// 3. Вызовы глобального slog пишут в JSON:\n\tslog.Info("Глобальный JSON-логгер успешно инициализирован", "env", "production")\n\n\t// 4. Даже старый пакет log теперь пишет через slog:\n\tlog.Println("Сообщение из старого пакета log")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Глобальный JSON-логгер успешно инициализирован","env":"production"}\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Сообщение из старого пакета log"}'}], 'under_the_hood': '`slog.SetDefault` адаптирует старый стандартный пакет `log.Default()` к новому `slog.Handler`.', 'pitfalls': 'Вызывайте `slog.SetDefault` в самом начале `func main()` до запуска горутин и модулей.', 'bigtech_interview': '**Вопрос с собеседования:** «Что происходит со старым пакетом log после вызова slog.SetDefault(jsonLogger)?»\n**Ответ:** Старый пакет `log` автоматически перенаправляет все вызовы `log.Println` в новый `slog.Handler`, форматируя их как JSON с уровнем `INFO`.'}, {'num': 71, 'title': 'Реализация архитектуры Security Observability и GDPR Audit Trail', 'task': 'Реализуй **Security Observability**:\n- Audit logs: `who accessed what data when`\n- Anomaly detection: `unusual access pattern` (user accessing 1000x normal records)\n- Alert: `possible data exfiltration` → SOC team\n- Metrics: `failed_auth_attempts`, `permission_denied_rate`\n- Compliance: GDPR data access log, HIPAA audit trail', 'theory': 'Security Observability обеспечивает непрерывный аудит безопасности: фиксацию доступа к персональным данным (GDPR/152-ФЗ), обнаружение утечек и выгрузок (Data Exfiltration) и оповещение SOC (Security Operations Center).', 'step_by_step': '1. Создадим структуру аудит-события `SecurityAuditLog`.\n2. Реализуем детектор аномального скачивания данных (>100 записей).\n3. Сгенерируем алерт в SOC при обнаружении эксфильтрации.\n4. В `main` смоделируем аудит.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log/slog"\n\t"os"\n)\n\nfunc LogSecurityAccess(logger *slog.Logger, actorID string, resource string, recordCount int, ip string) {\n\t// 1. Обязательный аудит доступа по GDPR/152-ФЗ\n\tlogger.Info("SECURITY_AUDIT: Data Access Granted",\n\t\tslog.String("compliance", "GDPR-Art-30"),\n\t\tslog.String("actor_id", actorID),\n\t\tslog.String("resource", resource),\n\t\tslog.Int("records_accessed", recordCount),\n\t\tslog.String("client_ip", ip),\n\t)\n\n\t// 2. Детектор аномальной выгрузки данных\n\tif recordCount > 500 {\n\t\tlogger.Error("SECURITY_ALERT: Possible Data Exfiltration Detected!",\n\t\t\tslog.String("alert_type", "ANOMALOUS_BULK_EXPORT"),\n\t\t\tslog.String("actor_id", actorID),\n\t\t\tslog.Int("volume", recordCount),\n\t\t\tslog.String("target_action", "NOTIFY_SOC_TEAM_P1"),\n\t\t)\n\t}\n}\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\n\tfmt.Println("=== 1. Обычный аудит доступа к профилю ===")\n\tLogSecurityAccess(logger, "user_45", "/api/v1/profile", 1, "192.168.1.50")\n\n\tfmt.Println("\\n=== 2. Аномальная выгрузка 2500 записей (Алерт в SOC) ===")\n\tLogSecurityAccess(logger, "user_45", "/api/v1/customers/export", 2500, "192.168.1.50")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# === 1. Обычный аудит доступа к профилю ===\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"SECURITY_AUDIT: Data Access Granted","compliance":"GDPR-Art-30","actor_id":"user_45","resource":"/api/v1/profile","records_accessed":1,"client_ip":"192.168.1.50"}\n# \n# === 2. Аномальная выгрузка 2500 записей (Алерт в SOC) ===\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"SECURITY_AUDIT: Data Access Granted","compliance":"GDPR-Art-30","actor_id":"user_45","resource":"/api/v1/customers/export","records_accessed":2500,"client_ip":"192.168.1.50"}\n# {"time":"2026-09-02T18:40:00Z","level":"ERROR","msg":"SECURITY_ALERT: Possible Data Exfiltration Detected!","alert_type":"ANOMALOUS_BULK_EXPORT","actor_id":"user_45","volume":2500,"target_action":"NOTIFY_SOC_TEAM_P1"}'}], 'under_the_hood': 'Аудит-логи безопасности часто направляются в защищенное WORM-хранилище (Write Once, Read Many), где их невозможно удалить даже с правами root.', 'pitfalls': 'В аудит-логах нельзя писать сами персональные данные (номера паспортов) — логируется только факт доступа субъекта к ресурсу.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы требования стандарта безопасности SOC2 к логированию доступа?»\n**Ответ:** Логи должны содержать точный таймстемп в UTC, идентификатор сотрудника (User ID), IP-адрес, тип действия (Read/Write/Delete) и результат (Success/Denied), сохраняясь не менее 365 дней.'}, {'num': 72, 'title': 'Красивое JSON форматирование контекстных пар в slog.Info', 'task': '**Атрибуты в `slog`**: Добавь в лог контекст (key-value пары). `slog.Info("юзер вошел", "user_id", 42, "ip", "127.0.0.1")`. Посмотри, как красиво это форматируется в JSON.', 'theory': 'При передаче пар "ключ-значение" в JSON-логгер `slog` автоматически трансформирует типы Go в соответствующие нативные JSON типы (`number`, `string`, `boolean`).', 'step_by_step': '1. Создадим JSON логгер.\n2. Вызовем `slog.Info("юзер вошел", "user_id", 42, "ip", "127.0.0.1", "active", true)`.\n3. В `main` убедимся в чистоте формата JSON.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log/slog"\n\t"os"\n)\n\nfunc main() {\n\thandler := slog.NewJSONHandler(os.Stdout, nil)\n\tslog.SetDefault(slog.New(handler))\n\n\tslog.Info("юзер вошел",\n\t\t"user_id", 42,\n\t\t"ip", "127.0.0.1",\n\t\t"active", true,\n\t\t"role", "developer",\n\t)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"юзер вошел","user_id":42,"ip":"127.0.0.1","active":true,"role":"developer"}'}], 'under_the_hood': 'Сериализатор `slog` форматирует JSON-числа без кавычек (`42`), строки в кавычках (`"127.0.0.1"`), а булевы флаги как `true`/`false`.', 'pitfalls': 'Не передавайте сложные структуры без `LogValuer`, иначе они будут сериализованы через рефлексию.', 'bigtech_interview': '**Вопрос с собеседования:** «Как в JSON выводе slog настроить форматирование времени в RFC3339Nano?»\n**Ответ:** Настроить `ReplaceAttr`: `if a.Key == slog.TimeKey { return slog.String(a.Key, a.Value.Time().Format(time.RFC3339Nano)) }`.'}, {'num': 73, 'title': 'Создание No-Op логгера через io.Discard для тихих юнит-тестов', 'task': 'Создай **no-op logger** (silent logger), который игнорирует все вызовы. Используй для тестов, чтобы не засорять консоль.', 'theory': 'No-Op Logger (Silent Logger) отбрасывает весь вывод с нулевыми затратами на форматирование строк. Для стандартного `log` используется `io.Discard`, а для `slog` — обработчик с `Enabled() == false` или `NewTextHandler(io.Discard, nil)`.', 'step_by_step': '1. Создадим No-Op `*log.Logger`: `log.New(io.Discard, "", 0)`.\n2. Создадим No-Op `*slog.Logger`: `slog.New(slog.NewTextHandler(io.Discard, nil))`.\n3. Запишем логи и убедимся в 0 выводе в терминал.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"log"\n\t"log/slog"\n)\n\nfunc main() {\n\t// 1. Silent логгер для стандартного пакета log\n\tsilentLog := log.New(io.Discard, "", 0)\n\tsilentLog.Println("Этот лог не будет напечатан в тестах")\n\n\t// 2. Silent логгер для slog\n\tsilentSlog := slog.New(slog.NewTextHandler(io.Discard, nil))\n\tsilentSlog.Info("Этот slog также полностью заглушен")\n\n\tfmt.Println("No-Op логгеры успешно инициализированы: в консоли 0 мусора!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# No-Op логгеры успешно инициализированы: в консоли 0 мусора!'}], 'under_the_hood': '`io.Discard` реализует `io.Writer`, возвращая `len(p), nil` без каких-либо операций записи в память или системных вызовов.', 'pitfalls': 'В юнит-тестах всегда внедряйте No-Op логгер, чтобы `go test ./...` выводил только результаты выполнения тестов.', 'bigtech_interview': '**Вопрос с собеседования:** «Как сделать абсолютно нулевые накладные расходы для no-op slog.Logger?»\n**Ответ:** Реализовать `type NullHandler struct{}`, чей метод `Enabled(context.Context, slog.Level) bool` всегда возвращает `false`. В этом случае `slog` даже не будет вычислять переданные аргументы лога!'}, {'num': 74, 'title': 'Логирование фатальных ошибок перед вызовом os.Exit(1)', 'task': 'Логируйте все фатальные ошибки перед вызовом `os.Exit` или `log.Fatal`.', 'theory': 'Завершение процесса без предварительного логирования причины делает систему "черным ящиком". Всегда записывайте критический контекст (порт, путь к конфигу, код ошибки) до вызова `os.Exit(1)`.', 'step_by_step': '1. Создадим функцию старта приложения `initApplication(configPath string) error`.\n2. В `main` перехватим ошибку.\n3. Запишем `slog.Error` с контекстом.\n4. Завершим работу через `os.Exit(1)`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n\t"log/slog"\n\t"os"\n)\n\nfunc initStorage(path string) error {\n\treturn errors.New("диск переполнен: No space left on device")\n}\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\n\tconfigPath := "/etc/storage/disks.json"\n\terr := initStorage(configPath)\n\tif err != nil {\n\t\t// Обязательное подробное логирование перед аварийным выходом\n\t\tlogger.Error("ФАТАЛЬНЫЙ СБОЙ: Не удалось инициализировать хранилище",\n\t\t\tslog.String("config_path", configPath),\n\t\t\tslog.String("error", err.Error()),\n\t\t\tslog.Int("exit_code", 1),\n\t\t)\n\t\tfmt.Println("[EMERGENCY] Завершение процесса с кодом 1")\n\t\t// В реальном приложении: os.Exit(1)\n\t\treturn\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"ERROR","msg":"ФАТАЛЬНЫЙ СБОЙ: Не удалось инициализировать хранилище","config_path":"/etc/storage/disks.json","error":"диск переполнен: No space left on device","exit_code":1}\n# [EMERGENCY] Завершение процесса с кодом 1'}], 'under_the_hood': 'Запись структурированного лога перед вызовом `os.Exit` позволяет оркестратору Kubernetes сохранить причину сбоя в `kubectl logs`.', 'pitfalls': 'Убедитесь, что буферы вывода сброшены до `os.Exit(1)`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему CrashLoopBackOff в Kubernetes требует качественного логирования перед os.Exit?»\n**Ответ:** Потому что pod быстро умирает и перезапускается. Если перед выходом нет структурированного лога с причиной, диагностика аварии займет часы вместо 1 минуты.'}, {'num': 75, 'title': 'Перехват необработанной паники с дампом debug.Stack() перед выходом', 'task': 'Перехватите необработанную панику в программе, залогировав её полный стек вызовов (stack trace) с помощью `debug.Stack()` перед аварийным завершением (`os.Exit(1)`).', 'theory': 'Функция `debug.Stack()` из стандартного пакета `runtime/debug` возвращает полный дамп стека текущей горутины в виде среза байт `[]byte`. Это позволяет записать стек в лог-файл или систему мониторинга до завершения процесса.', 'step_by_step': '1. Зарегистрируем верхнеуровневый `defer func() { if r := recover(); r != nil { ... } }()`.\n2. Получим срез байт стека `stack := debug.Stack()`.\n3. Запишем `slog.Error` с сообщением паники и текстом стека.\n4. В `main` смоделируем панику.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log/slog"\n\t"os"\n\t"runtime/debug"\n)\n\nfunc riskyOperation() {\n\tvar ptr *int\n\t*ptr = 42 // Инициирует runtime panic: nil pointer dereference\n}\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\n\tdefer func() {\n\t\tif r := recover(); r != nil {\n\t\t\tstackTrace := string(debug.Stack())\n\t\t\tlogger.Error("НЕОБРАБОТАННАЯ ПАНИКА В ГОРУТИНЕ",\n\t\t\t\tslog.Any("panic_value", r),\n\t\t\t\tslog.String("stack_trace", stackTrace),\n\t\t\t)\n\t\t\tfmt.Println("[CRASH HANDLER] Стек-трейс успешно сохранен в логи перед выходом")\n\t\t}\n\t}()\n\n\tfmt.Println("Запуск рискованной операции...")\n\triskyOperation()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Запуск рискованной операции...\n# {"time":"2026-09-02T18:40:00Z","level":"ERROR","msg":"НЕОБРАБОТАННАЯ ПАНИКА В ГОРУТИНЕ","panic_value":"runtime error: invalid memory address or nil pointer dereference","stack_trace":"goroutine 1 [running]:\\nruntime/debug.Stack()\\n\\t/usr/local/go/src/runtime/debug/stack.go:26\\nmain.main.func1()\\n\\t/home/ut/work/go-workout/main.go:21\\n..."}\n# [CRASH HANDLER] Стек-трейс успешно сохранен в логи перед выходом'}], 'under_the_hood': '`debug.Stack()` захватывает фреймы стека через системный механизм `runtime.Stack`.', 'pitfalls': 'В HTTP-серверах стандартный `net/http` автоматически перехватывает паники хендлеров, но их обязательно нужно перехватывать и в собственных горутинах `go func()`, иначе сервис упадет.', 'bigtech_interview': '**Вопрос с собеседования:** «Защищает ли defer recover() в main() от паники внутри запущенной фоновой горутины go worker()?\n**Ответ:** НЕТ! Паника привязана к конкретной горутине. Если паника возникла внутри `go worker()`, она не всплывет в `main()`, а сразу уронит весь процесс, если внутри самого `worker()` нет собственного `defer recover()`.'}, {'num': 76, 'title': 'Собственная реализация ротации логов по размеру 1MB', 'task': 'Напиши программу с **ротацией логов**: при достижении размера файла 1MB создаётся новый файл, старый переименовывается в `app.log.1`, `app.log.2` и т.д. (простая реализация без внешних пакетов).', 'theory': 'Ротация логов без внешних зависимостей строится на проверке размера файла перед записью (`file.Stat()`). При достижении порога файл закрывается, переименовывается через `os.Rename` и открывается заново с флагом `os.O_TRUNC`.', 'step_by_step': '1. Создадим структуру `SizeRotatingWriter struct { basePath string; maxBytes int64; count int; file *os.File }`.\n2. В методе `Write(p []byte)` проверим текущий размер.\n3. Если `size + len(p) >= maxBytes`, вызовем `rotate()`.\n4. В `main` запишем данные и проверим создание файлов `app.log` и `app.log.1`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log"\n\t"os"\n)\n\ntype SizeRotatingLogger struct {\n\tbasePath string\n\tmaxBytes int64\n\tcurrent  *os.File\n\tcount    int\n}\n\nfunc NewSizeRotatingLogger(basePath string, maxBytes int64) (*SizeRotatingLogger, error) {\n\tf, err := os.OpenFile(basePath, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0644)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\treturn &SizeRotatingLogger{basePath: basePath, maxBytes: maxBytes, current: f}, nil\n}\n\nfunc (l *SizeRotatingLogger) rotate() error {\n\t_ = l.current.Close()\n\tl.count++\n\tbackupName := fmt.Sprintf("%s.%d", l.basePath, l.count)\n\n\tif err := os.Rename(l.basePath, backupName); err != nil {\n\t\treturn err\n\t}\n\tfmt.Printf("[ROTATION] Лог-файл ротирован в %s\\n", backupName)\n\n\tf, err := os.OpenFile(l.basePath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0644)\n\tif err != nil {\n\t\treturn err\n\t}\n\tl.current = f\n\treturn nil\n}\n\nfunc (l *SizeRotatingLogger) Log(msg string) error {\n\tinfo, err := l.current.Stat()\n\tif err != nil {\n\t\treturn err\n\t}\n\n\tif info.Size() >= l.maxBytes {\n\t\tif err := l.rotate(); err != nil {\n\t\t\treturn err\n\t\t}\n\t}\n\n\t_, err = fmt.Fprintln(l.current, msg)\n\treturn err\n}\n\nfunc (l *SizeRotatingLogger) Close() {\n\tif l.current != nil {\n\t\t_ = l.current.Close()\n\t}\n}\n\nfunc main() {\n\tbase := "app_custom_rot.log"\n\t// Лимит 50 байт для наглядной демонстрации ротации\n\trotLogger, err := NewSizeRotatingLogger(base, 50)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tdefer func() {\n\t\trotLogger.Close()\n\t\t_ = os.Remove(base)\n\t\t_ = os.Remove(base + ".1")\n\t}()\n\n\t_ = rotLogger.Log("Line 1: Server initialized successfully")\n\t_ = rotLogger.Log("Line 2: User auth token generated")\n\t_ = rotLogger.Log("Line 3: Cache sync completed")\n\n\tfmt.Println("Процесс ротации успешно отработал")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [ROTATION] Лог-файл ротирован в app_custom_rot.log.1\n# Процесс ротации успешно отработал'}], 'under_the_hood': '`os.Rename` атомарен на уровне файловой системы POSIX, исключая потерю дескрипторов.', 'pitfalls': 'При наличии нескольких параллельных процессов запись в ротируемый файл требует межпроцессной блокировки `flock`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Linux ротацию логов часто доверяют внешней утилите logrotate с сигналом SIGHUP?»\n**Ответ:** Чтобы не усложнять код сервиса. Утилита `logrotate` переименовывает файл на уровне ОС и посылает процессу Go сигнал `SIGHUP` или `SIGUSR1`, по которому сервис просто закрывает старый и открывает новый дескриптор лога.'}, {'num': 77, 'title': 'Фильтрация логов по порогу slog.LevelWarn', 'task': '**Уровни логирования в `slog`**: Создай настройку уровня логов `&slog.HandlerOptions{Level: slog.LevelWarn}`. Вызови `slog.Debug`, `slog.Info` и `slog.Warn`. Убедись, что Debug и Info не выводятся в консоль.', 'theory': 'При установке уровня `LevelWarn` обработчик автоматически отсекает все записи с уровнем ниже `slog.LevelWarn` (то есть `LevelDebug = -4` и `LevelInfo = 0`). Выводятся только `LevelWarn = 4` и `LevelError = 8`.', 'step_by_step': '1. Создадим опции `opts := &slog.HandlerOptions{Level: slog.LevelWarn}`.\n2. Инициализируем `logger := slog.New(slog.NewTextHandler(os.Stdout, opts))`.\n3. Вызовем `Debug`, `Info`, `Warn`, `Error`.\n4. В `main` убедимся, что напечатаны только Warn и Error.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log/slog"\n\t"os"\n)\n\nfunc main() {\n\topts := &slog.HandlerOptions{\n\t\tLevel: slog.LevelWarn,\n\t}\n\n\tlogger := slog.New(slog.NewTextHandler(os.Stdout, opts))\n\tslog.SetDefault(logger)\n\n\tfmt.Println("=== Порог логирования: WARN и выше ===")\n\tslog.Debug("Скрытый Debug: детали состояния кэша")\n\tslog.Info("Скрытый Info: успешная обработка HTTP")\n\tslog.Warn("Предупреждение: диск заполнен на 85%", "disk", "/var/log")\n\tslog.Error("Ошибка: отказ подключения к базе данных", "db", "primary")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# === Порог логирования: WARN и выше ===\n# time=2026-09-02T18:40:00.000Z level=WARN msg="Предупреждение: диск заполнен на 85%" disk=/var/log\n# time=2026-09-02T18:40:00.000Z level=ERROR msg="Ошибка: отказ подключения к базе данных" db=primary'}], 'under_the_hood': 'Метод `Enabled(ctx, level)` сравнивает целочисленные значения уровней.', 'pitfalls': 'Если передать `Level: nil`, логгер по умолчанию использует `slog.LevelInfo`.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы числовые значения всех стандартных уровней slog?»\n**Ответ:** `slog.LevelDebug = -4`, `slog.LevelInfo = 0`, `slog.LevelWarn = 4`, `slog.LevelError = 8`.'}, {'num': 78, 'title': 'Хелпер LogError с автоматическим захватом места вызова через runtime.Caller', 'task': 'Напиши функцию `LogError(err error, attrs ...slog.Attr)`, которая форматирует ошибку с контекстом в JSON через `slog.Error`. Добавь атрибуты: функция, файл, строка (через `runtime.Caller`).', 'theory': 'Функция `runtime.Caller(1)` определяет файл, номер строки и имя вызывающей функции, автоматически добавляя координаты места сбоя в JSON-атрибуты лога.', 'step_by_step': '1. Напишем функцию `LogError(logger *slog.Logger, err error, attrs ...slog.Attr)`.\n2. Вызовем `pc, file, line, ok := runtime.Caller(1)`.\n3. Извлечем имя функции через `runtime.FuncForPC(pc).Name()`.\n4. Сформируем и запишем `logger.LogAttrs(...)` с уровнем `LevelError`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"errors"\n\t"log/slog"\n\t"os"\n\t"path/filepath"\n\t"runtime"\n)\n\nfunc LogError(logger *slog.Logger, err error, extraAttrs ...slog.Attr) {\n\tif err == nil {\n\t\treturn\n\t}\n\n\t// 1. Определение места вызова ошибки\n\tpc, file, line, ok := runtime.Caller(1)\n\tfnName := "unknown"\n\tif ok {\n\t\tfnName = runtime.FuncForPC(pc).Name()\n\t}\n\n\t// 2. Сбор атрибутов\n\tcallerGroup := slog.Group("caller",\n\t\tslog.String("function", fnName),\n\t\tslog.String("file", filepath.Base(file)),\n\t\tslog.Int("line", line),\n\t)\n\n\tallAttrs := []slog.Attr{\n\t\tslog.String("error", err.Error()),\n\t\tcallerGroup,\n\t}\n\tallAttrs = append(allAttrs, extraAttrs...)\n\n\t// 3. Запись ошибки\n\tlogger.LogAttrs(context.Background(), slog.LevelError, "Произошла ошибка выполнения", allAttrs...)\n}\n\nfunc processInvoice() error {\n\treturn errors.New("недостаточно средств на расчетном счете")\n}\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\n\terr := processInvoice()\n\tif err != nil {\n\t\tLogError(logger, err, slog.Int("invoice_id", 99482), slog.String("currency", "RUB"))\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"ERROR","msg":"Произошла ошибка выполнения","error":"недостаточно средств на расчетном счете","caller":{"function":"main.main","file":"main.go","line":48},"invoice_id":99482,"currency":"RUB"}'}], 'under_the_hood': 'Параметр `skip = 1` в `runtime.Caller(1)` пропускает сам хелпер `LogError` и захватывает точку вызова в функции `main`.', 'pitfalls': 'Используйте `filepath.Base(file)`, чтобы не раздувать логи длинными абсолютными путями файловой системы.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему важно оборачивать caller метаданные в slog.Group("caller")?»\n**Ответ:** Чтобы изолировать технические поля источника (`caller.file`, `caller.line`) от бизнес-полей лога, сохраняя чистоту корневой схемы JSON-документа.'}, {'num': 79, 'title': 'Комплексная связка: UserService с валидацией, хранилищем и логированием slog', 'task': 'Свяжите всё вместе: создайте структуру `UserService` с методом `CreateUser`. Он должен валидировать данные (возвращая кастомную ошибку), записывать пользователя в мапу (эмуляция БД) и логировать успех или провал через `slog`.', 'theory': 'Архитектура бизнес-сервиса объединяет валидацию входных данных (DTO Validation), доменные ошибки, хранилище данных и структурированное логирование всех операций.', 'step_by_step': '1. Объявим структуру `UserDTO{Email, Role}` и кастомную ошибку `ValidationError`.\n2. Создадим `UserService` с `sync.RWMutex`, `map[int]UserDTO` и `*slog.Logger`.\n3. В методе `CreateUser` выполним валидацию, запись и логирование.\n4. В `main` протестируем успешный и ошибочный сценарии.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n\t"log/slog"\n\t"os"\n\t"strings"\n\t"sync"\n)\n\nvar (\n\tErrInvalidEmail = errors.New("некорректный email адрес")\n\tErrInvalidRole  = errors.New("недопустимая роль пользователя")\n)\n\ntype UserDTO struct {\n\tID    int\n\tEmail string\n\tRole  string\n}\n\ntype UserService struct {\n\tmu     sync.RWMutex\n\tusers  map[int]UserDTO\n\tnextID int\n\tlogger *slog.Logger\n}\n\nfunc NewUserService(logger *slog.Logger) *UserService {\n\treturn &UserService{\n\t\tusers:  make(map[int]UserDTO),\n\t\tnextID: 1,\n\t\tlogger: logger.With(slog.String("service", "UserService")),\n\t}\n}\n\nfunc (s *UserService) CreateUser(email, role string) (UserDTO, error) {\n\t// 1. Валидация\n\tif !strings.Contains(email, "@") {\n\t\ts.logger.Warn("Неуспешная попытка создания пользователя: невалидный email",\n\t\t\tslog.String("email", email),\n\t\t\tslog.String("error", ErrInvalidEmail.Error()),\n\t\t)\n\t\treturn UserDTO{}, ErrInvalidEmail\n\t}\n\n\tif role != "admin" && role != "user" {\n\t\ts.logger.Warn("Неуспешная попытка создания: неизвестная роль",\n\t\t\tslog.String("email", email),\n\t\t\tslog.String("role", role),\n\t\t)\n\t\treturn UserDTO{}, ErrInvalidRole\n\t}\n\n\t// 2. Запись в хранилище под блокировкой\n\ts.mu.Lock()\n\tuser := UserDTO{ID: s.nextID, Email: email, Role: role}\n\ts.users[user.ID] = user\n\ts.nextID++\n\ts.mu.Unlock()\n\n\t// 3. Успешный лог\n\ts.logger.Info("Пользователь успешно зарегистрирован",\n\t\tslog.Int("user_id", user.ID),\n\t\tslog.String("email", user.Email),\n\t\tslog.String("role", user.Role),\n\t)\n\n\treturn user, nil\n}\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\tsvc := NewUserService(logger)\n\n\tfmt.Println("=== 1. Успешное создание пользователя ===")\n\t_, _ = svc.CreateUser("alex@company.ru", "admin")\n\n\tfmt.Println("\\n=== 2. Ошибка валидации email ===")\n\t_, _ = svc.CreateUser("bad-email-format", "user")\n\n\tfmt.Println("\\n=== 3. Ошибка валидации роли ===")\n\t_, _ = svc.CreateUser("john@corp.io", "superhero")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# === 1. Успешное создание пользователя ===\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Пользователь успешно зарегистрирован","service":"UserService","user_id":1,"email":"alex@company.ru","role":"admin"}\n# \n# === 2. Ошибка валидации email ===\n# {"time":"2026-09-02T18:40:00Z","level":"WARN","msg":"Неуспешная попытка создания пользователя: невалидный email","service":"UserService","email":"bad-email-format","error":"некорректный email адрес"}\n# \n# === 3. Ошибка валидации роли ===\n# {"time":"2026-09-02T18:40:00Z","level":"WARN","msg":"Неуспешная попытка создания: неизвестная роль","service":"UserService","email":"john@corp.io","role":"superhero"}'}], 'under_the_hood': '`sync.RWMutex` защищает внутреннюю мапу от состояния гонки при параллельных запросах.', 'pitfalls': 'Не логируйте ошибки валидации с уровнем `ERROR` — ошибки пользовательского ввода являются штатной ситуацией (`LevelWarn` или `LevelInfo`). Уровень `ERROR` резервируется для системных сбоев инфраструктуры.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему ошибки клиентской валидации (4xx) нужно логировать как WARN/INFO, а не ERROR?»\n**Ответ:** Ошибки уровня ERROR служат триггером для алертов дежурным инженерам SRE. Если логировать неверные пароли пользователей как ERROR, сервис будет генерировать ложные ночные алерты.'}, {'num': 80, 'title': 'Обработка открытия файла с градацией логов: Warn при отсутствии и Error при отказе', 'task': '**[Практический кейс]**: Напиши мини-программу, которая пытается открыть несуществующий файл. Если файла нет, пишет `Warn` в лог и создает его. Если есть другая ошибка (например, нет прав), пишет `Error` и завершает работу через `os.Exit(1)`.', 'theory': 'Градация уровней логирования при работе с файловой системой:\n1. Файл не существует (`errors.Is(err, os.ErrNotExist)`) -> `WARN` (штатная восстановимая ситуация, создаем файл).\n2. Отказ в доступе (`os.ErrPermission`) -> `ERROR` (критический системный сбой конфигурации).', 'step_by_step': '1. Попытаемся открыть файл через `os.Open(path)`.\n2. Если `errors.Is(err, os.ErrNotExist)` — пишем `logger.Warn` и вызываем `os.Create(path)`.\n3. При других ошибках — пишем `logger.Error`.\n4. В `main` протестируем работу логики.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n\t"log/slog"\n\t"os"\n)\n\nfunc OpenOrCreateConfig(logger *slog.Logger, path string) (*os.File, error) {\n\tfile, err := os.Open(path)\n\tif err == nil {\n\t\tlogger.Info("Конфигурационный файл успешно открыт", "path", path)\n\t\treturn file, nil\n\t}\n\n\t// Проверяем причину ошибки\n\tif errors.Is(err, os.ErrNotExist) {\n\t\tlogger.Warn("Файл не найден. Создание нового файла конфигурации по умолчанию",\n\t\t\tslog.String("path", path),\n\t\t\tslog.String("action", "auto_create"),\n\t\t)\n\n\t\tnewFile, createErr := os.Create(path)\n\t\tif createErr != nil {\n\t\t\tlogger.Error("Критическая ошибка создания файла",\n\t\t\t\tslog.String("path", path),\n\t\t\t\tslog.String("error", createErr.Error()),\n\t\t\t)\n\t\t\treturn nil, createErr\n\t\t}\n\t\t_, _ = newFile.WriteString(`{"environment": "production"}`)\n\t\treturn newFile, nil\n\t}\n\n\t// Другая критическая ошибка (например, нет прав доступа)\n\tlogger.Error("Критический сбой доступа к файловой системе",\n\t\tslog.String("path", path),\n\t\tslog.String("error", err.Error()),\n\t)\n\treturn nil, err\n}\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\ttargetPath := "app_config_autocreated.json"\n\n\t// Убедимся, что файла нет\n\t_ = os.Remove(targetPath)\n\n\tfile, err := OpenOrCreateConfig(logger, targetPath)\n\tif err != nil {\n\t\tfmt.Printf("Завершение: %v\\n", err)\n\t\treturn\n\t}\n\tdefer func() {\n\t\tfile.Close()\n\t\t_ = os.Remove(targetPath)\n\t}()\n\n\tfmt.Println("Файл успешно подготовлен к работе")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"WARN","msg":"Файл не найден. Создание нового файла конфигурации по умолчанию","path":"app_config_autocreated.json","action":"auto_create"}\n# Файл успешно подготовлен к работе'}], 'under_the_hood': '`errors.Is(err, os.ErrNotExist)` проверяет системный код ошибки `syscall.ENOENT`.', 'pitfalls': 'Не забывайте закрывать дескриптор `file.Close()` после завершения работы.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие os.IsNotExist(err) от errors.Is(err, os.ErrNotExist)?»\n**Ответ:** `errors.Is(err, os.ErrNotExist)` — современный стандарт Go 1.13+, корректно распаковывающий цепочки обернутых ошибок `%w`. `os.IsNotExist` — устаревшая функция, не поддерживающая развертывание кастомных типов ошибок.'}, {'num': 81, 'title': 'Собственный легковесный JSON-логгер без сторонних зависимостей', 'task': 'Структурированное логирование: напишите функцию, которая выводит JSON-строку с полями `"level"`, `"msg"`, `"time"` (без внешних библиотек).', 'theory': 'Понимание внутреннего устройства JSON-форматирования помогает писать высокопроизводительные логгеры без рефлексии и внешних пакетов с использованием `time.RFC3339` и `json.Marshal`.', 'step_by_step': '1. Создадим структуру `LogEntry struct { Time string; Level string; Message string; Fields map[string]any }`.\n2. Реализуем функцию `LogJSON(level, msg string, fields map[string]any)`.\n3. Сериализуем запись в `os.Stdout`.\n4. В `main` протестируем вывод.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"encoding/json"\n\t"fmt"\n\t"os"\n\t"time"\n)\n\ntype CustomLogRecord struct {\n\tTime    string         `json:"time"`\n\tLevel   string         `json:"level"`\n\tMsg     string         `json:"msg"`\n\tContext map[string]any `json:"context,omitempty"`\n}\n\nfunc LogJSON(level, msg string, fields map[string]any) {\n\trecord := CustomLogRecord{\n\t\tTime:    time.Now().UTC().Format(time.RFC3339),\n\t\tLevel:   level,\n\t\tMsg:     msg,\n\t\tContext: fields,\n\t}\n\n\tdata, err := json.Marshal(record)\n\tif err != nil {\n\t\tfmt.Fprintf(os.Stderr, "JSON encode error: %v\\n", err)\n\t\treturn\n\t}\n\n\t_, _ = fmt.Fprintln(os.Stdout, string(data))\n}\n\nfunc main() {\n\tLogJSON("INFO", "Сервер успешно запущен", map[string]any{\n\t\t"port": 8080,\n\t\t"tls":  true,\n\t\t"mode": "standalone",\n\t})\n\n\tLogJSON("ERROR", "Сбой авторизации пользователя", map[string]any{\n\t\t"user_id": 991,\n\t\t"ip":      "10.20.30.40",\n\t})\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Сервер успешно запущен","context":{"mode":"standalone","port":8080,"tls":true}}\n# {"time":"2026-09-02T18:40:00Z","level":"ERROR","msg":"Сбой авторизации пользователя","context":{"ip":"10.20.30.40","user_id":991}}'}], 'under_the_hood': 'Тег `omitempty` скрывает поле `context`, если передан пустой `map`.', 'pitfalls': 'Использование `encoding/json` для каждой записи создает аллокации в куче. В highload-библиотеках (`slog`, `zap`) JSON формируется прямой записью байт в буфер без рефлексии.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему slog.NewJSONHandler работает быстрее encoding/json.Marshal?»\n**Ответ:** Потому что `slog.JSONHandler` пишет байты ключей и значений напрямую в предвыделенный буфер без рефлексивного анализа полей структур и создания промежуточных `map[string]any`.'}, {'num': 82, 'title': 'Вложенная группировка параметров через slog.Group в вызове Info', 'task': '**slog Группы**: Используй `slog.Group("db", slog.String("host", "localhost"), slog.Int("port", 5432))` внутри вызова `slog.Info`, чтобы сгруппировать поля в JSON-логе под одним ключом `"db": {...}`.', 'theory': '`slog.Group(key, attrs...)` внутри вызова логирования структурирует связанные параметры в единый JSON-объект, предотвращая захламление корневого пространства ключей.', 'step_by_step': '1. Создадим JSON логгер.\n2. Вызовем `logger.Info` с группой `"db"` и группой `"pool"`.\n3. В `main` убедимся в правильности JSON дерева.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"log/slog"\n\t"os"\n)\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\n\tlogger.Info("Инициализация подключения к кластеру баз данных",\n\t\tslog.Group("db",\n\t\t\tslog.String("host", "localhost"),\n\t\t\tslog.Int("port", 5432),\n\t\t\tslog.String("database", "production_db"),\n\t\t),\n\t\tslog.Group("pool",\n\t\t\tslog.Int("max_open", 50),\n\t\t\tslog.Int("max_idle", 10),\n\t\t),\n\t)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"INFO","msg":"Инициализация подключения к кластеру баз данных","db":{"host":"localhost","port":5432,"database":"production_db"},"pool":{"max_open":50,"max_idle":10}}'}], 'under_the_hood': '`slog.Group` конструирует `slog.Attr` со значением `KindGroup`.', 'pitfalls': 'Вложенные группы можно создавать рекурсивно: `slog.Group("cluster", slog.Group("node1", ...))`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как обращаться к полям групп в запросах Elasticsearch?»\n**Ответ:** По точечной нотации (Dot Notation): `db.host: "localhost" AND pool.max_open: 50`.'}, {'num': 83, 'title': 'Structured Error Logging с захватом стека вызовов и параметров', 'task': 'Напиши программу с **structured error logging**: при ошибке логируется не только сообщение, но и стек вызовов (используй `runtime.Caller` в цикле для сбора стека), тип ошибки, входные параметры функции. Обсуди, когда это избыточно.', 'theory': 'Structured Error Logging объединяет:\n1. Сообщение ошибки и исходный тип (`reflect.TypeOf(err)`).\n2. Стек вызовов в виде массива строк.\n3. Входные параметры функции для точного воспроизведения бага в QA/Dev окружении.', 'step_by_step': '1. Напишем функцию сбора фреймов стека `getCallStack() []string`.\n2. Реализуем функцию `LogDetailedError(logger *slog.Logger, msg string, err error, params map[string]any)`.\n3. В `main` смоделируем ошибку расчета скидки и залогируем все детали.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n\t"log/slog"\n\t"os"\n\t"reflect"\n\t"runtime"\n)\n\nfunc getCallStack() []string {\n\tvar stack []string\n\t// Обходим стек фреймов\n\tfor i := 2; i < 6; i++ {\n\t\tpc, file, line, ok := runtime.Caller(i)\n\t\tif !ok {\n\t\t\tbreak\n\t\t}\n\t\tfn := runtime.FuncForPC(pc).Name()\n\t\tstack = append(stack, fmt.Sprintf("%s:%d in %s", file, line, fn))\n\t}\n\treturn stack\n}\n\nfunc LogDetailedError(logger *slog.Logger, op string, err error, inputParams map[string]any) {\n\tif err == nil {\n\t\treturn\n\t}\n\n\tlogger.Error("Сбой при выполнении доменной операции",\n\t\tslog.String("operation", op),\n\t\tslog.String("error_message", err.Error()),\n\t\tslog.String("error_type", reflect.TypeOf(err).String()),\n\t\tslog.Any("input_params", inputParams),\n\t\tslog.Any("stack_trace", getCallStack()),\n\t)\n}\n\nfunc calculateDiscount(orderID int, discountPercent float64) error {\n\tif discountPercent > 50.0 {\n\t\treturn errors.New("превышен лимит максимальной скидки (max 50%)")\n\t}\n\treturn nil\n}\n\nfunc main() {\n\tlogger := slog.New(slog.NewJSONHandler(os.Stdout, nil))\n\n\torderID := 77182\n\tdiscount := 75.0\n\n\terr := calculateDiscount(orderID, discount)\n\tif err != nil {\n\t\tLogDetailedError(logger, "calculateDiscount", err, map[string]any{\n\t\t\t"order_id":         orderID,\n\t\t\t"discount_percent": discount,\n\t\t})\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"time":"2026-09-02T18:40:00Z","level":"ERROR","msg":"Сбой при выполнении доменной операции","operation":"calculateDiscount","error_message":"превышен лимит максимальной скидки (max 50%)","error_type":"*errors.errorString","input_params":{"discount_percent":75,"order_id":77182},"stack_trace":["/home/ut/work/go-workout/main.go:53 in main.main"]}'}], 'under_the_hood': '`reflect.TypeOf(err)` определяет конкретную реализацию ошибки (`*os.PathError`, `*net.OpError` и др.).', 'pitfalls': 'Избыточность: Не логируйте стектрейс и параметры при штатных ошибках (пользователь ввел неверный пароль или пустую строку) — это раздувает объем хранилища логов.', 'bigtech_interview': '**Вопрос с собеседования:** «В каких случаях подробное логирование входных параметров (input_params) опасно?»\n**Ответ:** 1) Риск утечки секретов и паролей. 2) Нарушение GDPR при передаче персональных данных. 3) Переполнение памяти, если входным параметром является многомегабайтный срез `[]byte`.'}, {'num': 84, 'title': 'Строгая фильтрация уровней: пропуск Info и прохождение Warn/Error', 'task': '**Уровни логирования в `slog`**: Создайте обработчик `slog` с явным указанием уровня логирования `LevelWarn`. Попробуйте вывести логи уровней `Info`, `Warn` и `Error`. Убедитесь, что логи уровня `Info` автоматически отфильтровались и не попали в поток вывода.', 'theory': 'Фильтрация уровней в `slog` происходит до форматирования записи: метод `Enabled(ctx, LevelInfo)` возвращает `false`, предотвращая любые вычисления и выделения памяти для отфильтрованных логов.', 'step_by_step': '1. Создадим обработчик с `slog.HandlerOptions{Level: slog.LevelWarn}`.\n2. Инициализируем логгер.\n3. Вызовем `logger.Info("info лог")`, `logger.Warn("warn лог")`, `logger.Error("error лог")`.\n4. В `main` убедимся, что выведены только Warn и Error.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"log/slog"\n\t"os"\n)\n\nfunc main() {\n\t// Явная настройка минимального уровня LevelWarn\n\topts := &slog.HandlerOptions{\n\t\tLevel: slog.LevelWarn,\n\t}\n\thandler := slog.NewJSONHandler(os.Stdout, opts)\n\tlogger := slog.New(handler)\n\n\tfmt.Println("=== Проверка фильтрации уровней (LevelWarn) ===")\n\t// Этот лог будет отфильтрован:\n\tlogger.Info("Пользователь запросил список товаров", "category", "smartphones")\n\n\t// Эти логи попадут в вывод:\n\tlogger.Warn("Медленный ответ от внешнего сервиса геолокации", "latency_ms", 850)\n\tlogger.Error("Критический сбой: потеряна репликация PostgreSQL", "node", "replica-02")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# === Проверка фильтрации уровней (LevelWarn) ===\n# {"time":"2026-09-02T18:40:00Z","level":"WARN","msg":"Медленный ответ от внешнего сервиса геолокации","latency_ms":850}\n# {"time":"2026-09-02T18:40:00Z","level":"ERROR","msg":"Критический сбой: потеряна репликация PostgreSQL","node":"replica-02"}'}], 'under_the_hood': '`slog.Logger.Info` проверяет `h.Enabled(ctx, LevelInfo)`. Если `false`, выполнение метода немедленно завершается.', 'pitfalls': 'Если вы динамически меняете уровень логов, используйте `*slog.LevelVar` вместо константы `slog.LevelWarn`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в современных Go логгерах метод Enabled вызывается до передачи аргументов?»\n**Ответ:** Для исключения лишних аллокаций памяти и расходов CPU на подготовку аргументов лога (`fmt.Sprintf`, сериализация структур), если текущий уровень логирования отключен.'}]
